style.css:
/* Pinkie Pie Simple Theme */

html, body {
  background-color: #F5A9C6 !important; /* light pink */
  color: #000000 !important;
  font-family: "Georgia", sans-serif !important;
}

/* Headings in dark pink */
h1, h2, h3, h4, h5, h6 {
  color: #ED4587 !important;
}

/* Links: blue -> pink on hover */
a {
  color: #7EC6F9 !important;
}
a:hover {
  color: #ED4587 !important;
}

/* Buttons in yellow */
button, input[type=button], input[type=submit] {
  background-color: #F9EC7E !important;
  color: #ED4587 !important;
  border: none !important;
  border-radius: 8px !important;
  padding: 5px 10px !important;
}
button:hover, input[type=button]:hover, input[type=submit]:hover {
  background-color: #ED4587 !important;
  color: #ffffff !important;
}
